INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(3141, 'koKR', 'Loramus', 'Chcesz więc walczyć z demonami? Dobrze zrobisz, jeśli wysłuchasz mojej opowieści.', 'Wysłuchaj opowieści Loramusa Thalipedesa.', 'Opowieść Loramusa', '', '', '', '', '', 0),
(3381, 'koKR', 'Spotkanie z mistrzem', 'Ach, $gmłody:młoda; $r $gprzyszedł:przyszła; porozmawiać z Sanathem. Cóż za wspaniały dzień! Jestem zaszczycony, że $graczyłeś:raczyłaś; mnie swoją obecnością. Dziękuję!$B$BProszę... nie bądź na tyle $garogancki:arogancka;, by brać mój sarkazm za komplement. Wyjaśnijmy sobie jedno: nie lubię cię. Ale ta mała rozmowa nie dotyczy nas, tylko mojego mistrza.$B$BPrzynieś mi kilka piór hipogryfa na moje strzały, a pozwolę ci się z nim zobaczyć. Prosił, żebym przysyłał do niego poszukiwaczy przygód, jeśli okażą się dość godni.', 'Przynieś 2 nieuszkodzone pióra hipogryfa Sanathowi Lim-yo w Aszarze, jeśli chcesz porozmawiać z jego mistrzem.', '', 'Wróć do Sanatha Lim-yo w Aszarze.', '', '', '', '', 0),
(3382, 'koKR', 'Załoga pod ostrzałem', 'Płynęliśmy tuż przy brzegu w poszukiwaniu bezpiecznej przystani, gdzie moglibyśmy rzucić kotwicę. Słońce zaszło nie dalej niż godzinę wcześniej, gdy zaatakowały... te przeklęte nagi!$B$BNie wiem, czego szukały, ale najwyraźniej tego nie znalazły – już raz wróciły. Kilku moich zwiadowców trzyma wartę u wejścia do doliny, żeby w porę nas ostrzec, gdy nadejdzie kolejny atak.$B$BPrzykro mi, że $gtrafiłeś:trafiłaś; tu akurat teraz, $N, ale nic na to nie poradzę.$B$BJesteś $ggotów:gotowa; na walkę swojego życia?', 'Obroń kapitan Vanessę Beltis, jej załogę i pasażerów „Zwiadowcy Horyzontu” przed atakiem nag. Kapitan Vanessa Beltis musi przeżyć.', 'Ochroń kapitan Vanessę Beltis przed atakiem nag', 'Wróć do kapitan Vanessy Beltis w Aszarze.', '', '', '', '', 0),
(3383, 'koKR', '', '', '', '', 'Wróć do kapitan Vanessy Beltis w Aszarze.', '', '', '', '', 0),
(3384, 'koKR', '', '', '', '', 'Wróć do Rolanda Trybodłubka na Zrujnowanych Rubieżach w Aszarze.', '', '', '', '', 0),
(3421, 'koKR', 'Droga powrotna', '', '', '', '', '', '', '', '', 0),
(3503, 'koKR', 'Spotkanie z mistrzem', '', '', '', '', '', '', '', '', 0),
(3508, 'koKR', 'Złamanie bariery', 'Jesteś $glekkomyślny:lekkomyślna;, $N. To godna podziwu cecha twojego rodzaju – ślepo rzucać się do walki, gdy szanse na sukces są niewielkie albo żadne. Pomogę ci, choćby po to, by zobaczyć upadek choć jednego sługi Razelikha.$B$BZłamanie bariery, która chroni podwładnych Razelikha, zajmie czas i będzie wymagało zdobycia rzadkich artefaktów.$B$BNie ruszaj się, muszę najpierw odprawić rytuał oświecenia. Wiedza, którą zdobędę, pomoże mi wykuć broń wielkiej mocy.', 'Zaczekaj, aż Loramus dokończy zaklęcie oświecenia.', '', '', '', '', '', '', 0),
(3509, 'koKR', 'Imię bestii', 'Jest tylko jeden sposób, by zranić władcę demonów i jego sługi. Trzeba wykuć broń mocy, która będzie nosić jego prawdziwe imię.$B$BGdy taka broń zostanie wykuta, demon i wszyscy pod jego rozkazami staną się wrażliwi na ciosy.$B$BW Aszarze mieszka pomniejsze bóstwo: lord Arkkoroc. Musisz go odszukać, ale uważaj – jeśli cię odkryją, jego sługi zrobią wszystko, by cię zniszczyć.$B$BZa takie informacje z pewnością przyjdzie ci zapłacić.', 'Porozmawiaj z lordem Arkkorokiem w Aszarze. Zacznij poszukiwania Świątyni Arkkoranu na brzegu morza.', '', '', '', '', '', '', 0),
(3510, 'koKR', 'Imię bestii', 'Ona zabija moje dzieci, $gśmiertelniku:śmiertelniczko;. Ta, która mieni się władczynią tych oceanów. Fałszywa bogini, nic więcej. Zmiażdż ją i przynieś wszystkie jej głowy.$B$BZa to otrzymasz imię, którego szukasz, i coś równie ważnego.$B$BKrąży po lęgowisku... Zwą ją Heterą.$B$B<Lord Arkkoroc wskazuje na południowy zachód.>$B$BIdź!$B', 'Zabij Heterę i przynieś lordowi Arkkorokowi zakrwawioną głowę Hetery, pobitą głowę Hetery i posiniaczoną głowę Hetery.', '', 'Wróć do lorda Arkkoroca w Świątyni Arkkoranu w Aszarze.', '', '', '', '', 0),
(3511, 'koKR', 'Imię bestii', 'Jak obiecałem, wyjawię imię władcy demonów, Razelikha Plugawiciela. Najpierw jednak muszę przygotować coś niezwykle ważnego na twoją podróż.$B$BBroń, którą chcesz stworzyć, wymaga hartowania. Daj mi chwilę na wyciśnięcie krwi z tych głów.$B$B<Lord Arkkoroc ściska głowy w swoich olbrzymich pięściach, wyciskając z nich krew.>$B$BZanieś Loramusowi tę krew do hartowania wraz z imieniem bestii: Rakh\'likh.', 'Zanieś krew do hartowania Loramusowi Thalipedesowi.$B', '', '', '', '', '', '', 0),
(3517, 'koKR', 'Kradzież wiedzy', 'Przyznaję, $N, że wykorzystałam swoje położenie w Aszarze najlepiej, jak się dało. Kara od Belgroma ma swoje dobre strony.$B$BZanim wyruszyłam, trochę się rozeznałam i $gzdziwiłbyś:zdziwiłabyś; się, ile cennych rzeczy tu leży.$B$BOpowiem ci więcej o moich interesach, a nawet dam ci udział w zyskach, jeśli pomożesz mi część z nich zebrać.$B$BW Ruinach Eldarath na wschodzie są tablice, których potrzebuję. Wszystkie cztery noszą imiona czarodziejów Wysoko Urodzonych. Zdobądź je dla mnie, a porozmawiamy dalej.', 'Znajdź tablicę Beth\'Amara, tabliczkę Jin\'yael, tablicę Markri i tablicę Sael\'hai, a następnie wróć do Jedigi w Aszarze.', '', 'Wróć do Jedigi w Aszarze.', '', '', '', '', 0),
(3561, 'koKR', 'Dostawa dla arcymaga Xylema', 'Ta ostatnia tablica trafi do kogoś bardzo niebezpiecznego, $N. Posłuchaj mnie: ufam tej osobie znacznie mniej niż komukolwiek innemu, z kim kazałam ci się spotkać.$B$BArcymag Xylem ma wieżę na wzgórzach górujących nad Aszarą. Jest człowiekiem, ale nie zachowuje się jak żaden człowiek, którego spotkałam... albo zabiłam. Bije od niego moc, a ja nie śmiem pytać, co zamierza zrobić z tą tablicą.$B$BSam do mnie przyszedł i powiedział, że jego ochroniarz Sanath pomoże mi dostać się do wieży, gdy będę gotowa się z nim spotkać. Szukaj Sanatha na północy.', 'Przynieś tablicę Sael\'hai arcymagowi Xylemowi w Aszarze.', '', '', '', '', '', '', 0),
(3565, 'koKR', 'Zapłata Xylema dla Jedigi', 'O co chodzi? Ach tak, twoja zapłata. Oczywiście.$B$BWeź to i zmykaj. Jestem pewien, że Jediga czeka na twój powrót z jakże wielką cierpliwością.', 'Dostarcz liścik Xylema Jedidze w Aszarze.', '', '', '', '', '', '', 0),
(3601, 'koKR', 'Też mi Kim\'jael!', 'Też mi Kim\'jael!! Wiesz, co „Kim\'jael” znaczy u krwawych elfów, $N? Mały szczur... czy coś w tym stylu. Wielkie łobuzy!$B$BNajęli mnie, żebym pomógł im przeszukać okolicę w poszukiwaniu jakichś zaginionych skarbów. Jasne, że wskoczyłem na pokład, jak tylko powiedzieli „skarb” i ile są gotowi zapłacić, ale oczywiście obrócili się przeciwko mnie i próbowali mnie zabić... MNIE!$B$BCo tylko pokazuje, że krwawym elfom nie można ufać.$B$BKłopot w tym, że wciąż mają mój sprzęt, a ja nie mogę go odzyskać. Pomożesz mi?', 'Przeszukaj Obóz Thalasyjski i znajdź kompas, lunetę, wypchaną kurę i dynksomajster Kim\'jaela, a następnie zwróć je właścicielowi w Aszarze.', '', 'Wróć do Kim\'jaela w Obozie Thalasyjskim w Aszarze.', '', '', '', '', 0),
(3602, 'koKR', 'Azsharyt', 'Prastare klifowe olbrzymy z południowej części Aszary żywią się skałami i budowlami tej krainy. Odchodami po takim posiłku jest niezwykle plastyczny i niezwykle wytrzymały kryształ zwany azsharytem.$B$BJego formacje zaśmiecają cały południowy łuk, ale niewiele z nich udaje się zdobyć, bo olbrzymy są wyjątkowo gwałtowne.$B$BUdasz się na południe i zdobędziesz tyle azsharytu, ile trzeba do wykonania korpusu broni. Moje ogary spaczenia pomogą ci odnaleźć kryształ.', 'Zdobądź 20 skrystalizowanych azsharytów w południowej Aszarze. Możesz skorzystać z pomocy ogara spaczenia, który „wywęszy” sprytnie ukryte złoża.$B$BGdy wykonasz zadanie, wróć do Loramusa.$B', '', '', '', '', '', '', 0),
(5141, 'koKR', '', '', 'Przynieś 2 twarde napierśniki ze skorpiady, 2 twarde rękawice ze skorpiady i 10 zużytych smoczych łusek Peterowi Galenowi w Aszarze.$B$BWykonanie tego zadania da ci dostęp do sztuki garbarstwa smoczołuskiego.$B$BWykonanie tego zadania uniemożliwi ci naukę garbarstwa żywiołów i garbarstwa plemiennego; zanim to zrobisz, upewnij się, że chcesz podążać tą ścieżką.', '', 'Wróć do Petera Galena w Ruinach Eldarath w Aszarze.', '', '', '', '', 0),
(5534, 'koKR', '„Zaginiony” sprzęt Kim\'jaela', 'Co?! Co?!$B$BTo ci nie wystarczy? Wiesz, ile kosztują te materiały wybuchowe? Idą po... a, nieważne. Dobra, chcesz zarobić prawdziwe pieniądze? Bo tak się robi interesy: udowadniasz, że jesteś $gcennym pracownikiem:cenną pracownicą;, a jak trochę wytrwasz, dostajesz należytą nagrodę.$B$BJeśli jesteś $g„cennym” pracownikiem:„cenną” pracownicą;, to ruszaj do Ruin Eldarath i znajdź mi jakąś runę, której szukały te krwawe elfy. Podobno mają ją nagi.', 'Znajdź jakąś runę, którą mają nagi w Ruinach Eldarath, i przynieś ją Kim\'jaelowi w Aszarze.', '', 'Wróć do Kim\'jaela w Obozie Thalasyjskim w Aszarze.', '', '', '', '', 0),
(5535, 'koKR', 'Niespokojne duchy', 'Dawno temu Wysoko Urodzeni byli jednymi z najpotężniejszych adeptów tajemnej magii, jakich wydały nocne elfy. Zepsucie, które towarzyszy takim studiom, wyrządziło wiele szkód społeczności nocnych elfów i mocno odbiło się na całym Azeroth... o czym z pewnością dobrze wiesz.$B$BObiecałem Strażniczkom, że będę uwalniał duchy z ich śmiertelnych więzów, gdy tylko je znajdę. Jeśli zrobisz to samo, na pewno zdołam cię jakoś wynagrodzić.$B$BDuchy nawiedzają Kaplicę Cienistej Pieśni na północny wschód stąd.', 'Zniszcz 6 zjaw Wysoko Urodzonych i 6 liszek Wysoko Urodzonych, a następnie wróć do Loh\'atu w Aszarze.', '', 'Wróć do Loh\'atu nad Rzeką Południowej Furii w Jesionowej Kniei.', '', '', '', '', 0),
(5536, 'koKR', 'Ziemia pełna nienawiści', 'Satyry, wynaturzone, złe oblicze nocnych elfów, zatruwają teraz święte ziemie, po których niegdyś stąpał Cenarius. Nie mogę mówić za nocne elfy, jeśli chodzi o wszystkie okrucieństwa, jakich dopuściły się te demoniczne stwory, ale złożyłem Matce Ziemi przysięgę, że pomogę elfom oczyścić krainę z tej zarazy.$B$BJestem pewien, że się wykażesz, jeśli pomożesz mi je wytępić.$B$BNa północny wschód stąd znajdziesz klan Haldarr. Wróć do mnie, gdy zmierzysz się z ich potęgą.', 'Zabij 6 satyrów z Haldarr, 2 szachrajów z Haldarr i 2 zaprzysiężonych Spaczeniu z Haldarr, a następnie wróć do Loh\'atu na granicy Jesionowej Kniei.', '', 'Wróć do Loh\'atu nad Rzeką Południowej Furii w Jesionowej Kniei.', '', '', '', '', 0),
(6804, 'koKR', 'Zatruta woda', 'Oddział żywiołaków-zwiadowców wysłano na wschodnie plagowiska Lordaeronu, a tamtejsza choroba wypaczyła je i zaraziła. Władcy Wody nie mogą dopuścić do takiej zniewagi naszej czystości!$B$BWeź tę fiolkę. Jest w niej cząstka jednego z aspektów Neptulona. Użyta na zarażonych żywiołakach zwalczy truciznę w ich ciałach i je uleczy! Ale wewnętrzny konflikt doprowadzi je do wzbierającego szaleństwa.$B$BPokonaj te dysonansowe przypływy i przynieś mi ich karwasze wiążące.', 'Użyj Aspektu Neptulona na zatrutych żywiołakach we Wschodnich Plagowiskach. Przynieś 12 dysonansowych karwaszy i Aspekt Neptulona księciu Hydraxisowi w Aszarze.', '', 'Wróć do księcia Hydraxisa w Zatoce Burz w Aszarze.', '', '', '', '', 0),
(6805, 'koKR', 'Burzyciele i dudniacze', 'My, żywiołaki wody, toczymy wojnę z istotami pośledniejszych żywiołów. Jeśli naprawdę jesteś naszym sojusznikiem w tym konflikcie, okaż mi swoje przekonanie!$B$BDaleko na południu, w pustynnej krainie Silithus, słudzy powietrza i ziemi krzątają się w skalnym zakątku zwanym Kryształową Doliną. Chronią przedmioty mocy przed mniejszymi istotami, śmiertelnikami, i choć nie wiem, czemu to robią, pragnę pokrzyżować ich wysiłki.$B$BUdaj się do Kryształowej Doliny w Silithusie, pokonaj naszych wrogów i wróć do mnie.', 'Zabij 15 pyłowych burzycieli i 15 pustynnych dudniaczy, a następnie wróć do księcia Hydraxisa w Aszarze.', '', 'Wróć do księcia Hydraxisa w Zatoce Burz w Aszarze.', '', '', '', '', 0),
(6821, 'koKR', 'Oko Żarowidza', '$GUdowodniłeś:Udowodniłaś; mi, że potrafisz pokonać naszych wrogów i wykonywać misje, które służą sprawie Władców Wody. Ale do tej pory $gmierzyłeś:mierzyłaś; się tylko z pośledniejszymi przeciwnikami... Czy zwyciężysz, gdy staniesz naprzeciw potężnego wroga?$B$BTo jest twoje nowe zadanie.$B$BWysoko w Iglicy Czarnej Góry orkowie pojmali sługę ognia, Pirostrażnika Żarowidza. Znajdź miejsce jego uwięzienia, zabij jego strażników, a potem zabij żarowidza. Przynieś mi jego oko, a ukaże mi ono twoją wartość.', 'Przynieś Oko Żarowidza księciu Hydraxisowi w Aszarze.', '', 'Wróć do księcia Hydraxisa w Zatoce Burz w Aszarze.', '', '', '', '', 0),
(6822, 'koKR', 'Ognista Czeluść', '$N, może nadszedł czas, by poddać cię prawdziwej próbie. Jesteś $ggotów:gotowa;?$B$BNa dnie Otchłani Czarnej Góry jest przejście do Ognistej Czeluści. To twierdza naszego wroga, w rękach najpotężniejszych sług ognia na tym świecie.$B$BUdaj się do Ognistej Czeluści, $N. Pokaż mi, że masz siłę i wolę, by pokonać to, co tam znajdziesz.$B$BA jeśli masz sojuszników wśród swoich, zbierz ich. Tylko armia może liczyć na to, że wejdzie do Ognistej Czeluści i przeżyje.', 'Zabij 1 Władcę Ognia, 1 gorejącego olbrzyma, 1 pradawnego ognistego ogara i 1 lawowego bryzgacza, a następnie wróć do księcia Hydraxisa w Aszarze.', '', 'Wróć do księcia Hydraxisa w Zatoce Burz w Aszarze.', '', '', '', '', 0),
(6823, 'koKR', 'Agent Hydraxisa', 'Jeśli naprawdę pragniesz sojuszu z nami, zapraszam cię do wojny z naszymi wrogami, sługami powietrza, ziemi i ognia. Każda klęska, jaką im zadasz, osłabi ich pozycję w tym świecie i dowiedzie twojego oddania naszej sprawie.$B$BKampania będzie długa, ale jeśli wytrwasz, twoja chwała i honor będą wielkie.', 'Zdobądź reputację Szanowany u Hydraksjańskich Władców Wody, a następnie porozmawiaj z księciem Hydraxisem w Aszarze.', '', '', '', '', '', '', 0),
(6824, 'koKR', 'Ręce wroga', '$N, twoja służba jest dla nas bardzo cenna, więc niechętnie wysyłamy cię na tę ostatnią misję, bo nie chcemy stracić tak użytecznego agenta.$B$BAle jej powodzenie ogromnie pomogłoby nam w wojnie i... uznano, że warto zaryzykować twoje życie.$B$BChcemy, by zginęli ci dowódcy z Ognistej Czeluści: Lucyfron, Sulfuron, Gehennas i Shazzrah. Zabij ich i przynieś mi ich ręce!$B$BTo zadanie pochłonie wszystkie twoje siły, $N, ale jeśli zdołasz je wykonać, Władcy Ognia otrzymają straszliwy cios.', 'Przynieś ręce Lucyfrona, Sulfurona, Gehennasa i Shazzraha księciu Hydraxisowi w Aszarze.', '', 'Wróć do księcia Hydraxisa w Zatoce Burz w Aszarze.', '', '', '', '', 0),
(7486, 'koKR', 'Nagroda bohatera', '$N, twoje zasługi dla Władców Wody przerosły wszystko, czego mogliśmy się spodziewać po mieszkańcach tego świata.$B$BNie rozumiemy, co twój lud rozumie przez wdzięczność czy nagradzanie dobrych uczynków, ale w tym przypadku... być może nagroda jest uzasadniona.$B$BPod falami przy południowym brzegu tej wyspy znajdziesz szkatułę. W niej czeka twoja... nagroda.$B$BIdź, $N. Odbierz swoją nagrodę.', 'Odbierz nagrodę ze Szkatuły Hydraxisa.', '', '', '', '', '', '', 0),
(8153, 'koKR', 'Poroże rumaka', 'Rumak nosi najpotężniejsze poroże w znanych krainach. Służy mu ono do obrony: rumak bodzie nim napastnika i często przy tym uszkadza jego końce. Doskonałe, nietknięte poroże jest oznaką zwierzęcego ducha o najwyższej pewności siebie.$b$bKto trzyma takie poroże, zyskuje tę samą pewność siebie.$b$bUpoluj omszałokopytego rumaka, znajdź doskonałe poroże i przynieś mi je.', 'Przynieś doskonałe poroże rumaka Ogtinkowi w Aszarze. Ogtinc mieszka na szczycie klifów na północny wschód od Ruin Eldarath.', '', 'Wróć do Ogtinka na Strzaskanym Wybrzeżu w Aszarze.', '', '', '', '', 0),
(8231, 'koKR', 'Łowy na rozfalacze', 'Rozfalacz to ziemnowodna bestia, która żyje tylko tutaj, w Aszarze. Są potężne i wytrzymałe.$b$bTwarde, lśniące łuski rozfalacza odzwierciedlają siłę łowcy.$b$bTrop i poluj na rozfalacze wzdłuż wybrzeża Aszary, a potem przynieś mi ich łuski.', 'Przynieś 6 łusek rozfalacza Ogtinkowi w Aszarze. Ogtinc mieszka na szczycie klifów na północny wschód od Ruin Eldarath.', '', 'Wróć do Ogtinka na Strzaskanym Wybrzeżu w Aszarze.', '', '', '', '', 0),
(8232, 'koKR', 'Zielony smok', 'Teraz wysyłam cię na niebezpieczne łowy: zabij zielonego smoka Morphaza i przynieś mi jego ząb. Morphaz mieszka głęboko w Świątyni Atal\'Hakkar, do której wejście leży na Moczarach Smutków.$b$bJeśli chcesz go pokonać, nie możesz iść w pojedynkę. Ten smok ma wielu wrogów – poszukaj innych, którzy pragną go zniszczyć.$b$bZąb smoka symbolizuje siłę, jaką łowca znajduje we wspólnocie z innymi. Przynieś mi go, a wiele się nauczysz.', 'Przynieś Ząb Morphaza Ogtinkowi w Aszarze. Ogtinc mieszka na szczycie klifów na północny wschód od Ruin Eldarath.', '', 'Wróć do Ogtinka na Strzaskanym Wybrzeżu w Aszarze.', '', '', '', '', 0),
(8235, 'koKR', 'Zaszyfrowane fragmenty', 'Lord Ravenholdt poprosił nas obu o przysługę. Chce zdjąć zaklęcie z tej torby.$b$bNiestety, niedawno skradziono część moich ksiąg o rozpraszaniu magii, a dzikusy je zniszczyły. Szczątki tych ksiąg wciąż są dla mnie cenne.$b$bJeśli przyniesiesz mi dość zaszyfrowanych fragmentów, zdołam poskładać je w całość. Największą szansę masz, zabijając bestie Aszary, bo mają zwyczaj podnosić niemal wszystko.', 'Przynieś 10 zaszyfrowanych fragmentów arcymagowi Xylemowi w Aszarze.', '', '', '', '', '', '', 0),
(8251, 'koKR', 'Magiczny pył', 'Krwawe elfy w Aszarze opracowały metodę sproszkowywania zdobytych magicznych przedmiotów. Lśniący pył, który w ten sposób wytwarzają, różni się od składników zwykle uzyskiwanych zaklęciem odczarowania.$b$bGdy posłałem mojego ucznia, żeby wymienił się z nimi na ten pył, zabili go bez wahania. Muszą za to zapłacić.$b$bCzas rozmów się skończył, $N. Znajdź krwawe elfy na klifach Aszary i użyj bardziej „przekonujących” metod, by zdobyć ich lśniący pył.', 'Przynieś 10 lśniących pyłów arcymagowi Xylemowi.', '', 'Wróć do arcymaga Xylema w Wąwozie Mrocznego Szeptu w Zimozdroju.', '', '', '', '', 0),
(8252, 'koKR', 'Koral syren', 'Rozejrzyj się. Ruiny i plaże roją się od nag Jadowitego Bicza. Ostatnio te nędzne stwory nauczyły się rozpoznawać rzadkie składniki, które występują tylko w Aszarze.$b$bMówię konkretnie o zaczarowanym koralu – coś, czego nie znam, przyciąga je do niego. Teraz w zatoce zostało niewiele korali, a są one kluczowe dla moich badań. Musisz odebrać trochę zaczarowanego korala syrenom Jadowitego Bicza i mi go przynieść.', 'Zbierz 6 zaczarowanych korali i wróć do arcymaga Xylema.', '', 'Wróć do arcymaga Xylema w Wąwozie Mrocznego Szeptu w Zimozdroju.', '', '', '', '', 0),
(8253, 'koKR', 'Zniszcz Morphaza', 'Głęboko w zatopionej świątyni Atal\'Hakkar mieszka zielony smok imieniem Morphaz.$b$bLata temu pokonał mnie w zuchwałej zasadzce i połknął w całości mojego ucznia. Utrata ucznia nie jest mi obca, ale ten akurat niósł tajemny odłamek niezrównanej wielkości i jakości.$b$bMusisz zebrać potężnych sojuszników i zapuścić się do świątyni. Zniszcz Morphaza i odzyskaj tajemny odłamek z jego odwiecznego żołądka.', 'Odbierz Morphazowi tajemny odłamek i wróć do arcymaga Xylema.', '', '', '', '', '', '', 0),
(8255, 'koKR', 'Rumaki, a jakże', 'Omszałokopyte rumaki z Aszary to wspaniałe zwierzęta, które kiedyś żyły w Spaczonej Kniei. Są z natury odporne na choroby i trucizny, więc tamtejsze zepsucie ich nie dotknęło. W swej odwiecznej mądrości po prostu postanowiły opuścić to chore miejsce.$b$bSmuci to moje serce, ale muszę cię prosić, byś $gzapolował:zapolowała; na te potężne bestie. Zbierz cztery gruczoły rumaka jako pierwszy składnik maści leczniczej – maści, którą uleczymy Spaczoną Knieję.', 'Zdobądź 4 zdrowe gruczoły rumaka i przynieś je Ogtinkowi w Aszarze. Ogtinc mieszka na szczycie klifów na północny wschód od Ruin Eldarath.', '', 'Wróć do Ogtinka na Strzaskanym Wybrzeżu w Aszarze.', '', '', '', '', 0),
(8256, 'koKR', 'Posoka nieumarłych', 'Do tej maści leczniczej trzeba użyć prostej receptury: jedna część trucizny, dwie części lekarstwa. Jedno lekarstwo już $gzdobyłeś:zdobyłaś;, teraz musisz zebrać truciznę.$b$bPotężni nieumarli, tacy jak błąkający się Wysoko Urodzeni, którzy przemierzają Ruiny Eldarath, są czasem tak przesiąknięci złem, że zbiera się ono w chorobliwie zielonkawą maź. Żywi znają tę substancję jako posokę nieumarłych.$b$bZe względu na moc tego plugawego składnika potrzebuję tylko jednej porcji posoki.', 'Zdobądź posokę nieumarłych dla Ogtinca w Aszarze. Ogtinc mieszka na szczycie klifów na północny wschód od Ruin Eldarath.', '', 'Wróć do Ogtinka na Strzaskanym Wybrzeżu w Aszarze.', '', '', '', '', 0),
(8257, 'koKR', 'Krew Morphaza', 'Teraz ostatni składnik, drugie lekarstwo.$b$bWiadomo, że zielony smok Morphaz jest odporny na wszelkie trucizny i choroby – wielu druidów oddało życie, by zdobyć tę wiedzę. Nie ma wątpliwości, że jego krew ma moc, jakiej potrzebujemy.$b$bKurier Kręgu Cenariona zabierze składniki, które już $gzebrałeś:zebrałaś;, a ty zdobędziesz ostatni. Zwołaj sojuszników i odszukaj legowisko smoka w zatopionej świątyni Atal\'Hakkar. Zanieś jego krew Grecie Omszałe Kopyto w Spaczonej Kniei.', 'Zabij Morphaza w zatopionej świątyni Atal\'Hakkar i zanieś jego krew Grecie Omszałe Kopyto w Spaczonej Kniei. Wejście do zatopionej świątyni znajduje się na Moczarach Smutków.', '', 'Wróć do Grety Omszałe Kopyto w Szmaragdowym Sanktuarium w Spaczonej Kniei.', '', '', '', '', 0),
(9362, 'koKR', 'Watażka Krellian', 'Nie ma wiele czasu, $N! Moje czary jasnowidzenia wykryły potężne źródło magii. Nie mogę opuścić wieży, więc proszę cię, byś $gzabił:zabiła; nikczemnego stwora, który ma ten artefakt.$b$bTen żałosny kretyn zwie się watażka Krellian i kryje się za strażnikami w Świątyni Zin-Malor. Spal go na popiół i zabierz pryzmatyczną muszlę, której tak pożąda.', 'Zdobądź pryzmatyczną muszlę dla arcymaga Xylema. Arcymag mieszka w wieży na szczycie klifów Aszary.', '', '', '', '', '', '', 0),
(9364, 'koKR', 'Rozszczepiona magia', 'Moje badania odkryły wyjątkowe zastosowanie pryzmatycznej muszli.$b$bWeź muszlę ze sobą i rzuć Polimorfię na nagi Jadowitego Bicza w Aszarze. Jeśli odczekasz chwilę, chaotyczna aura muszli sprawi, że na krótko rozpadną się na kilka mniejszych klonów. Zabij te klony jak najszybciej, a muszla zbierze ich esencję.$b$bGdy muszla się napełni, przynieś mi ją.', 'Rzuć Polimorfię na nagi Jadowitego Bicza w Aszarze i zabij klony, które pojawią się kilka sekund później. Gdy zabijesz 50 klonów polimorfii, wróć do arcymaga Xylema w Aszarze.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(3141, 'koKR', 'Niech tak będzie...', 0),
(3381, 'koKR', 'Dwa pióra, tak jak prosiłem. I wcale niezłe.$b$bGotowe? Wystarczy słowo, a ruszasz w drogę.$b$bAch, i jeszcze raz: uważaj na siebie... mój mistrz nie przepada za imbecylami, ale jest bardzo hojny dla tych, którzy go zadowolą.', 0),
(3382, 'koKR', 'Udało się! Dziękuję! To była chyba jedna z najbrutalniejszych bitew, w jakich brałam udział. Nie potrafię ci się dość odwdzięczyć.$B$BSzkoda tylko, że tak niewielu z mojej załogi przetrwało tę próbę.$B$BPorozmawiaj, proszę, z ocalałymi pasażerami „Zwiadowcy Horyzontu”. Niektórzy mieli w tej okolicy interesy i może będą mieli do ciebie prośbę czy dwie, jeśli zechcesz pomóc. Jeszcze raz dziękuję za całą twoją pomoc.', 0),
(3421, 'koKR', 'Teraz odeślę cię z powrotem do obozu Sanatha.$B$BNie zważaj na jego złe maniery – jest niegrzeczny dla wszystkich z wyjątkiem mistrza. Może pewnego dnia dostanie nauczkę.', 0),
(3503, 'koKR', 'Były czasy, gdy mogłem żądać, czego tylko chciałem, od tych, którzy szukali mojego mistrza. Ale teraz wystarczy, że poprosisz, a poślę cię do niego.$b$bTo mnie drażni, ale nie kwestionuję jego rozkazów. Mogę się tylko nacieszyć wyśmiewaniem twoich idiotycznych ciuchów albo żałosnej miny. Nawet to mnie nudzi...$b$bNawet to gadanie mnie nudzi! Chcesz się zobaczyć z moim mistrzem czy nie?', 0),
(3508, 'koKR', 'Trzeba odkryć imię bestii.', 0),
(3509, 'koKR', 'Władca demonów?$b$b<Lord Arkkoroc się śmieje.>$b$bByć może ten, który tu stoi, pomoże ci tą informacją; ale najpierw ty musisz pomóc jemu.$b$b', 0),
(3510, 'koKR', 'Nareszcie ktoś godny mądrości Arkkoroca!', 0),
(3511, 'koKR', 'Krew do hartowania nada broni zjadliwość, której potrzebujemy do jej wykucia. Pozostał już tylko jeden krok, by ją stworzyć.', 0),
(3517, 'koKR', 'Doskonale, $N, i do tego w dobrym stanie. Powinniśmy za nie dostać dobrą cenę od wszystkich zainteresowanych.$b$bNie guzdrajmy się tu dłużej, niż musimy. Mamy pieniądze do zarobienia.', 0),
(3561, 'koKR', 'Ach, tablica Sael\'hai... jakże długo pragnąłem ją zbadać.$b$bDziękuję, $N. Możesz przekazać Jedidze, że dobrze się spisała. To z pewnością będzie warte zapłaty, której zażądała.', 0),
(3565, 'koKR', 'Żadnych problemów? Zupełnie żadnych? No, to już coś... Spodziewałam się, że będzie się ociągał albo przynajmniej złamie naszą umowę. Hmm, może jednak można mu ufać.$b$bNo cóż, nie ma co się nad tym rozwodzić. Oto twój udział. Dzięki za pomoc.', 0),
(3601, 'koKR', 'Haha! Nieźle ich $gurządziłeś:urządziłaś;, co?!$b$bŚwietnie! To nauczy te krwawe elfy zdradzać wspólników... zwłaszcza kogoś tak lojalnego jak goblini kupiec! Phi, krwawe elfy...!$b$bNo, przynajmniej zapłacę ci za fatygę... tak jak obiecałem.$b$bProszę bardzo... to powinno ci się przydać.', 0),
(3602, 'koKR', 'Twoje zadania w Aszarze dobiegły końca, $gśmiertelniku:śmiertelniczko;. Teraz muszę wykuć składniki potrzebne do kolejnego etapu twojej wyprawy.', 0),
(5141, 'koKR', 'Przyznaję – trzeba silnej woli, by podjąć tak nieodwracalną decyzję jak ta. Zapewniam cię, że garbarstwo smoczołuskie okaże się dla ciebie opłacalną i satysfakcjonującą ścieżką.$B$BAby w przyszłości szkolić się w tej sztuce, po prostu porozmawiaj ze mną, a udostępnię ci całą wiedzę, której jeszcze nie $gprzyswoiłeś:przyswoiłaś;.', 0),
(5534, 'koKR', 'Haha! Wspaniale!$b$bNa pewno dowiem się, do czego to służy i czemu magini Rimtori – ta krowa, która mnie wynajęła – tego chciała. Ha! Mam was, śmierdzące krwawe elfy! Kim\'jael! Ha! Pokażę im, kto tu jest szczurem!$b$bDobra robota, $N. Wielkie dzięki. Masz, weź te monety i zmykaj – muszę parę rzeczy przemyśleć.', 0),
(5535, 'koKR', 'Dobra robota, $N. Dziękuję za pomoc. Duchy zaznały spokoju, a zagrożenia, które przyciągało ich pragnienie tajemnej mocy, zmalały.$b$bJestem pewien, że obie strony konfliktu, który pustoszy Azeroth, dostrzegą, że stoisz ponad takimi sprawami.', 0),
(5536, 'koKR', 'Dobra robota, $N. Widzę, że jesteś nie tylko $gzręczny:zręczna;, ale i $gprzebiegły:przebiegła;. Pokonanie takich stworzeń świadczy o twojej wierności zasadom Matki Ziemi, nawet jeśli nie uznajesz jej za swoje bóstwo. Jest ona we wszystkim na tej planecie i poza nią. Jej oczy, jedno ciemne, a drugie jasne, wędrują po niebie i zawsze na nas spoglądają.$b$bProszę, przyjmij tych kilka monet w podzięce za to, czego $gdokonałeś:dokonałaś;.', 0),
(6804, 'koKR', 'Dobrze się $gspisałeś:spisałaś;, $N. Skażone żywiołaki, które $guleczyłeś:uleczyłaś;, były zniewagą dla wszystkich wód. Nasza siła tkwi w naszej czystości i jeśli mamy wygrać wojnę z innymi, musimy pozostać silni.', 0),
(6805, 'koKR', 'Twoja odwaga została dowiedziona, podobnie jak twoja wartość dla nas. Być może będę mieć dla ciebie kolejne zadania, bardziej godne cenionego sojusznika Władców Wody.', 0),
(6821, 'koKR', 'Ach, a więc masz w sobie siłę. I spryt, bo Iglica Czarnej Góry to coś więcej niż przeciwnik dla samej brutalnej siły.$B$BW istocie, $N, możesz jeszcze okazać się dla nas cennym sojusznikiem...', 0),
(6822, 'koKR', '$GDokonałeś:Dokonałaś; tego, co większość twojego rodzaju uznałaby za niemożliwe. $GStawiłeś:Stawiłaś; czoła istotom Ognistej Czeluści i $gzwyciężyłeś:zwyciężyłaś;!$B$BJak na tak małe stworzenie $gwykazałeś:wykazałaś; się wielką zaradnością.$B$BByć może pewnego dnia zawiążemy prawdziwy sojusz między twoim rodzajem a Władcami Wody.', 0),
(6823, 'koKR', 'Twoje czyny przeciw naszym wrogom rozbrzmiewają w komnatach Władców Wody, $N. Niektórzy sądzili, że twoja postać jest zbyt mała i krucha, by walczyć w naszej wojnie, ale $gosiągnąłeś:osiągnęłaś; wiele. $GZdobyłeś:Zdobyłaś; nasz szacunek, a to niewiarygodny wyczyn.', 0),
(6824, 'koKR', 'Masz ręce! $GPokonałeś:Pokonałaś; ognistych dowódców! Nie sądziłbym, że to możliwe, gdybym nie znał ciebie i twoich możliwości.$B$B$N, twoich wyczynów nie sposób zliczyć, ale wieść o tym ostatnim rozejdzie się falą wśród Władców Wody. Pewnego dnia twoje imię może stać się dla nas legendą.$B$BPorozmawiaj ze mną znowu, $N. Być może mam dla ciebie jeszcze jedno zadanie...', 0),
(7486, 'koKR', 'Głos Hydraxisa dobiega spod powierzchni wody...$B$B„Wybierz to, co najlepiej ci odpowiada, $N. Niech chroni cię przed wrogami Władców Wody”.', 0),
(8153, 'koKR', 'Aby je zdobyć, trzeba mieć bystry wzrok i wielką cierpliwość. Dobra robota.', 0),
(8231, 'koKR', 'Rozfalacze niełatwo pokonać, a już zwłaszcza w ich wodnym żywiole.$B$B$GUdowodniłeś:Udowodniłaś;, że jesteś $ggotów:gotowa; polować na jeszcze groźniejszą zdobycz.', 0),
(8232, 'koKR', '$GPoznałeś:Poznałaś; dawne obyczaje, $N, i dlatego ofiaruję ci dar z czasów mojej wędrówki jako $c.', 0),
(8235, 'koKR', 'Wygląda na to, że $gzebrałeś:zebrałaś; jedne z lepszych fragmentów. Może jednak nie jesteś $gbezużyteczny:bezużyteczna;.', 0),
(8251, 'koKR', 'Dobra robota, $N! Nie przestaje mnie zdumiewać, jak przekonująca potrafi być salwa tajemnych pocisków.', 0),
(8252, 'koKR', 'To znakomity okaz korala, $N. Twoje umiejętności są bez wątpienia precyzyjne i zabójcze.$B$BNie myśl, że twoje wysiłki przeszły niezauważone. Być może jesteś $ggodny:godna; prawdziwego sprawdzianu umiejętności...', 0),
(8253, 'koKR', 'Niewiarygodne. Odłamek urósł, przez długie lata wchłaniając energię smoka.$B$BNie mogę już od ciebie niczego więcej żądać. Dzięki temu odłamkowi odzyskałem pełną zdolność kształtowania tajemnej mocy. Moje pierwsze dzieło należy do ciebie, $N – wystarczy, że wybierzesz...', 0),
(8255, 'koKR', 'Dobrze, że boska ścieżka przywiodła cię do nas, $N. Twoje przekonania nie kolidują z zadaniami, jakich wymaga sporządzenie tej maści.$B$BWidzisz, rumak jest święty dla Kręgu Cenariona, a zabijanie go z jakiegokolwiek powodu, nawet koniecznego, osłabia ich ducha.', 0),
(8256, 'koKR', 'Nie powiem, że cieszy mnie ta paskudna substancja, ale to zło konieczne. Dziękuję, $N.', 0),
(8257, 'koKR', '$GZabiłeś:Zabiłaś; Morphaza i $gprzyniosłeś:przyniosłaś; nam jego krew... Nie mogę uwierzyć w tak dobre wieści!$B$BNatychmiast połączymy składniki i zaczniemy leczyć drzewa i stworzenia Spaczonej Kniei. Naprawienie tego, co się tu stało, zajmie całe życie, ale ty $gdałeś:dałaś; nam środki, by to zrobić.', 0),
(9362, 'koKR', 'Muszę przyznać, że ta muszla ma dziwną aurę. Wydaje się więc właściwe, by częścią twojej nagrody za jej zdobycie było wypróbowanie jej magicznych możliwości...', 0),
(9364, 'koKR', 'Wspaniale! Wspaniale!$B$BTeraz możemy przekształcić tę magię w nowe zaklęcie. Patrz!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(3141, 'koKR', 'Nie przerywaj mi, $gśmiertelniku:śmiertelniczko;.', 0),
(3381, 'koKR', 'Pozostaję tu na rozkaz mojego mistrza. Wolno mi żądać dowolnej ceny za przeniesienie do jego wieży. Na razie proszę każdego podróżnego tylko o dwa pióra, żebym mógł dalej wyrabiać moje słynne strzały.$b$bJeśli nie będziesz $guważał:uważała;, podniosę cenę. Co powiesz na pół tuzina sztuk złota?$b$bTak właśnie myślałem. Pilnuj się, a cena zostanie taka, jaka jest.', 0),
(3382, 'koKR', 'To będzie ciężka bitwa...', 0),
(3510, 'koKR', '<Lord Arkkoroc pochyla się, by ci się przyjrzeć.>$b$bGdzie one są?', 0),
(3511, 'koKR', '$GWróciłeś:Wróciłaś;! Zdumiewające. $GOdkryłeś:Odkryłaś; prawdziwe imię?', 0),
(3517, 'koKR', 'Tablice, które dla mnie zbierasz, powinny przynieść u właściwych ludzi niezły grosz. Powiem ci, komu trzeba je dostarczyć, gdy już je znajdziesz. Ale głupia nie jestem... swoją działkę dostaniesz, jak będę mieć dowód, że dotarły na miejsce.$b$bWięc bierz się do roboty – nie mamy całego dnia. Może będę musiała znaleźć kogoś innego do pomocy.', 0),
(3561, 'koKR', 'W czym mogę ci pomóc, $N?', 0),
(3565, 'koKR', 'No i co Xylem miał do powiedzenia? Nic ci nie zrobił, prawda? Nie rzucił na ciebie czaru? Nie namówił cię podstępem do pracy dla niego?', 0),
(3601, 'koKR', 'Te śmierdzące krwawe elfy. Mówię ci, gdybym był taki silny jak ty, sam bym tam poszedł i dał im nauczkę! Ale muszę się zadowolić tym, że zapłacę tobie, żebyś się nimi za mnie zajął.', 0),
(3602, 'koKR', 'Zło nie śpi, $ggłupcze:głupia;. Odpoczniesz, kiedy wreszcie umrzesz. A teraz przynieś mi te kryształy.', 0),
(5534, 'koKR', 'No i co, $N? Gdzie runa? Jesteś $gdobrym pracownikiem:dobrą pracownicą;, prawda? $GPrzyszedłeś:Przyszłaś; tu pomóc?$b$bNie każ mi się zastanawiać, czy zapłacić ci tyle, ile się umówiliśmy. Co? A, nic nie ustaliliśmy? No świetnie... to się nie spiesz – tylko wiedz, że dostaniesz dużo mniej, jak będziesz się grzebać.', 0),
(5535, 'koKR', 'Jak idą poszukiwania duchów Wysoko Urodzonych, $N?$B$BWiele wydarzeń przysporzyło wszystkim rasom Azeroth ogromnych cierpień, ale z jakiegoś powodu te duchy zdają się plagą dla wszystkich ludów. Może to przez ich nieustanne pragnienie wszelkiej tajemnej magii – takie pragnienie zwiastuje Płonący Legion, a wiemy, do czego to może prowadzić.', 0),
(5536, 'koKR', 'Jak idzie walka z satyrami, $N?$B$BCzy są tak silne, jak $gmyślałeś:myślałaś;? Silniejsze? A może nie mogą się równać z twoją siłą?', 0),
(6804, 'koKR', 'Masz karwasze?', 0),
(6805, 'koKR', 'Tchórzostwa nie darzymy szacunkiem, $N. Udaj się do Silithusa i dowiedź swojej odwagi.', 0),
(6821, 'koKR', 'Masz Oko, $N? Czy masz dość siły, by wejść do Iglicy Czarnej Góry?', 0),
(6822, 'koKR', 'Czeka na ciebie sukces w Ognistej Czeluści, $N.', 0),
(6824, 'koKR', '$GPokonałeś:Pokonałaś; Lucyfrona i pozostałych, $N? Masz ręce wroga?', 0),
(8153, 'koKR', 'Masz poroże?', 0),
(8231, 'koKR', 'Powiodło ci się?', 0),
(8232, 'koKR', 'Widzę mądrość w twoich oczach, $N. Czy twoje łowy dobiegły końca?', 0),
(8235, 'koKR', 'Czy masz już dość fragmentów, żebym mógł kontynuować pracę?', 0),
(8251, 'koKR', 'Masz pył?', 0),
(8252, 'koKR', 'Syreny Jadowitego Bicza są zaskakująco biegłymi magami. Chyba nie tak biegłymi jak ty?', 0),
(8253, 'koKR', 'Czy $gzabiłeś:zabiłaś; mojego dawnego wroga?', 0),
(8255, 'koKR', '$GWróciłeś:Wróciłaś;. Udało ci się?', 0),
(8256, 'koKR', 'Musimy szybko zdobyć posokę. $GZnalazłeś:Znalazłaś; ją?', 0),
(8257, 'koKR', 'Masz krew Morphaza?', 0),
(9362, 'koKR', 'Nie ma czasu do stracenia! Masz muszlę?', 0),
(9364, 'koKR', '$GZebrałeś:Zebrałaś; magię?', 0);
