(19990, 'koKR', 'Błogosławiony różaniec', 'Prawdziwego przyjaciela poznasz w biedzie, nie po różańcu.', 0),
(19991, 'koKR', 'Oko diabłozaura', '', 0),
(19992, 'koKR', 'Ząb diabłozaura', '', 0),
(20006, 'koKR', 'Krąg nadziei', 'Wykuty z czystego światła.', 0),
