(20023, 'koKR', 'Zaszyfrowany fragment', 'Tekst zapisano tajemnym językiem.', 0),
(20025, 'koKR', 'Krew Morphaza', '', 0),
(20027, 'koKR', 'Zdrowy gruczoł rumaka', '', 0),
(20029, 'koKR', 'Zaczarowany koral', '', 0),
(20030, 'koKR', 'Kamyk-pupil', 'Wygląda na szczęśliwego.', 0),
(20035, 'koKR', 'Lodowcowy kolec', 'Ostrze zdobią diabelskie runy.', 0),
(20036, 'koKR', 'Ognisty rubin', 'Nieprzewidywalność prowadzi zarówno do zwycięstwa, jak i do śmierci.', 0),
(20037, 'koKR', 'Wisior z tajemnym kryształem', 'Tajemne kryształy najlepiej służą celom maga.', 0),
(20082, 'koKR', 'Kostur biady', 'Biada tym, którzy staną naprzeciw.', 0),
(20083, 'koKR', 'Włócznia myśliwska', '', 0),
(20085, 'koKR', 'Tajemny odłamek', '', 0),
