INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1311, 'koKR', 'Do wszystkich zainteresowanych:$B$BJeśli czytasz ten liścik, to znajdujesz się w jednym z dwóch miejsc:$B$B(1) Na południowym półwyspie Aszary.$B$B(2) W brzuchu klifowego olbrzyma.$B$BOba równie niepożądane. $B$BNależy zaznaczyć, że swego czasu byłem w pierwszym z nich, a w chwili pisania tego listu jestem w drugim.', 0),
(1312, 'koKR', 'Pobyt w brzuchu olbrzyma daje człowiekowi czas do namysłu. $B$BGdy moje ciało zamienia się w kryształ, doszedłem do wniosku, że być może na tym świecie jest już dość bohaterów. Jeśli jakimś cudem wyjdę z tych tarapatów, ukręcę temu orkowi jego widmowy łeb!$B$B– Windan Shay', 0),
(1313, 'koKR', 'Co ja sobie myślałem? A może lepsze pytanie brzmi: co ja robię, pisząc liścik, gdy siedzę uwięziony w żołądku olbrzyma? Oba pytania są dobre i na żadne nie mam od ręki odpowiedzi... Przyznaję, moja wyprawa nie miała szlachetnych pobudek. Przybyłem w poszukiwaniu azsharytu, wyjątkowego kryształu z południowej Aszary. Ach, jakie bogactwa mogły być moje! Phi! A teraz spójrz na mnie...', 0),
(1314, 'koKR', 'Jeśli jakakolwiek rozumna istota znajdzie ten liścik, niech zada sobie pytanie: „Po jakiego diabła oni się włóczą wśród agresywnych olbrzymów wysokich na trzydzieści stóp?”\n\n– Mook', 0);
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(15481, 0, 0, 'koKR', 'POWIEDZIAŁEM: ŻEGNAJ!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(4469, 'koKR', 'Witaj, $Gpanie:pani;. Jestem Nyrill, uczeń mistrza Xylema. Jeśli masz jakieś sprawy, śmiało przedstaw je mistrzowi.$B$BBędę tu na twoje usługi, gdy zechcesz wrócić na dół, do podnóża góry.', '', 0),
(4641, 'koKR', '', 'Ahoj, $N! Niezbyt ładny widok, co?$B$B„Zwiadowca Horyzontu” na dnie morza, moja załoga w rozsypce, a ładunek i pasażerowie porozrzucani jak śmieci – można by pomyśleć, że to któryś z kanałów Wichrogrodu po festynie.$B$BA na tym kłopoty się nie kończą...', 0),
(4658, 'koKR', '', 'Przygotujcie się! Nagi nie będą długo czekać z wykorzystaniem przewagi, gdy się dowiedzą, że żyjemy.', 0),
(6290, 'koKR', 'Jeśli chcesz polować na smoki, proszę bardzo. Gdzie mam wysłać kondolencje?', '', 0),
(7591, 'koKR', 'Kraina Aszary.', 'Kraina Aszary.', 0),
(7592, 'koKR', 'Moja wiedza o dziejach nocnych elfów jest ograniczona, ale powiada się, że dawno temu – gdy nocne elfy wciąż uważały sztukę rzucania tajemnych zaklęć za świętą – Aszara była największą z nich. Piękna kobieta, którą obwołały królową. Niestety, to właśnie jej uzależnienie od tajemnej mocy stało się pewnego dnia zarzewiem najbardziej niszczycielskich wydarzeń w dziejach tego świata.', '', 0),
(7593, 'koKR', 'Ruiny Eldarath.', 'Ruiny Eldarath.', 0),
(7594, 'koKR', 'Wieża maga na północy.', 'Wieża maga na północy.', 0),
(7600, 'koKR', 'Furbolgi z plemienia Pyskodrzewnych.', 'Furbolgi z plemienia Pyskodrzewnych.', 0),
(7601, 'koKR', 'Obecność błękitnych smoków.', 'Obecność błękitnych smoków.', 0),
(7602, 'koKR', 'Ponieważ mi $gpomogłeś:pomogłaś;, opowiem ci, co wiem o tej krainie i o tym, co warto tu zobaczyć. Moja wiedza nie jest rozległa, ale może zdołam wskazać ci coś, co zainteresuje kogoś takiego jak ty.', '', 0),
(7603, 'koKR', 'Niegdyś było to wielkie miasto nocnych elfów, w którym władali Wysoko Urodzeni, praktykujący wielką i potężną magię tajemną. Teraz są przeklęci i nawiedzają te ziemie, a ich zrujnowane miasto padło ofiarą nag z plemienia Jadowitego Bicza. Słyszałem, że nagi przeszukują ruiny w poszukiwaniu potężnych artefaktów Wysoko Urodzonych.', '', 0),
(7604, 'koKR', 'Podobno na północy mieszka potężny ludzki mag; z nieznanych powodów czuwa nad tą krainą. Sam tam nie byłem, ale mówi się, że goście są mile widziani, a nawet mogą zyskać jego przychylność, jeśli zechcą załatwiać dla niego sprawunki.', '', 0),
(7605, 'koKR', 'W ostatnich latach widziałem, jak furbolgów spotykały straszne rzeczy – padali ofiarą na wielu frontach. Nie wiem jednak, co stało się z tym plemieniem. Czy dotknęła ich ta sama zaraza, która skaziła Spaczoną Knieję? A może po prostu gniewa ich to, co spotkało ich niegdyś pokojowy lud, i teraz chcą się bronić? Tak czy inaczej, większość z nich wydaje się wroga wobec przybyszów.', '', 0),
(7606, 'koKR', 'Samych błękitnych smoków tu nie ma, ale są wyznawcy Malygosa. Nie wiem dlaczego, ale jedno mogę ci powiedzieć: gdziekolwiek są błękitne smoki, tam spodziewaj się magii tajemnej. Nie zdziwiłbym się, gdyby smocze pomioty czegoś tu strzegły... być może czegoś, co zostawili po sobie Wysoko Urodzeni.', '', 0),
(8664, 'koKR', 'Jestem Hydraxis, książę Władców Wody. Nie jesteś żywiołakiem, więc nie możesz zrozumieć naszej walki, ale może zawrzemy umowę korzystną dla nas obu...', '', 0),
(8665, 'koKR', 'Dobrze cię widzieć, $N. Nasza wojna z innymi władcami żywiołów wciąż trwa, ale twoje wysiłki pomagają zapewnić nam zwycięstwo.', '', 0),
(8666, 'koKR', 'Potrzebuję fiolki wodnej kwintesencji, Hydraxisie, bo wyruszam do Ognistej Czeluści, by ugasić runę Władców Ognia.', 'Potrzebuję fiolki wodnej kwintesencji, Hydraxisie, bo wyruszam do Ognistej Czeluści, by ugasić runę Władców Ognia.', 0),
(8703, 'koKR', '$N, jesteś $ggotów:gotowa; na ostateczne zadanie. Ogniste runy wyryte na posadzce Ognistej Czeluści są przejściami do królestwa ognia, a ich obecność jest dla nas zniewagą i zarazem źródłem mocy dla Władców Ognia. Trzeba je ugasić!$B$BAby ugasić runę, weź fiolkę wodnej kwintesencji. Wylej ją na runę, a jej płomień zgaśnie – runa stanie się bezużyteczna, a nasz wróg osłabnie!', '', 0),
(8707, 'koKR', 'Porozmawiaj z Hydraxisem.', '', 0),
(8708, 'koKR', 'Nie masz ze mną żadnych spraw, maluchu.', '', 0),
(8709, 'koKR', 'Nie mów do mnie w tym swoim prostackim języku! Tylko Hydraxis jest w stanie go znieść.', '', 0),
(9071, 'koKR', 'Chodźcie, maluczcy. Stańcie przede mną!', '', 0),
(9072, 'koKR', 'To miejsce jest pod moją ochroną. Tajemnice magii tajemnej pozostaną nienaruszone.', '', 0),
(9073, 'koKR', 'Oto cena ciekawości.', '', 0),
(11015, 'koKR', 'Chcesz mnie skrzywdzić, $gśmiertelniku:śmiertelniczko;?', '', 0),
(11016, 'koKR', 'Jestem $gposzukiwaczem:poszukiwaczką; skarbów i szukam potężnych artefaktów. Oddaj mi je, a nic ci się nie stanie.', 'Jestem $gposzukiwaczem:poszukiwaczką; skarbów i szukam potężnych artefaktów. Oddaj mi je, a nic ci się nie stanie.', 0),
(11022, 'koKR', 'Moja warta jest wieczna, $gśmiertelniku:śmiertelniczko;.', '', 0),
(11033, 'koKR', 'Szukasz odłamka berła powierzonego pieczy Błękitnego Stada?$B$B<Azuregos zdaje się uśmiechać.>', '', 0),
(11034, 'koKR', 'Skąd wiedziałeś? To znaczy, tak... Tak, szukam tego odłamka. Masz go?', 'Skąd wiedziałeś? To znaczy, tak... Tak, szukam tego odłamka. Masz go?', 0),
(11035, 'koKR', 'Oczywiście, że nie mam odłamka. To byłoby idiotyczne. Chodzę wśród dzikusów po tej przeklętej krainie! Nie mogę zrobić pięciu kroków, żeby jakiś oszalały ork czy człowiek nie próbował wbić mi w skórę zaostrzonego patyka. W każdej chwili możesz równie dobrze rozmawiać z moim widmowym duchem.$B$BW każdym razie... ukryłem go.$B$BNo dalej... zapytaj gdzie.', '', 0),
(11036, 'koKR', 'No dobrze. Gdzie?', 'No dobrze. Gdzie?', 0),
(11037, 'koKR', 'Pokochasz tę historię. Rzecz w tym, że gdy tylko Malygos powierzył mi ochronę odłamka berła, wiedziałem, że czeka mnie wieczność bólu głowy i cierpienia.$B$BA ja chcę tylko badać te wybrzeża pełne magii i zbierać artefakty, które mogły ocaleć z Rozłamu. Wiesz, kiedyś kwitła tu cywilizacja Wysoko Urodzonych! Nie musisz mi mówić, że znajdzie się tu trochę porządnych magicznych przedmiotów. Czuję je nosem!', '', 0),
(11038, 'koKR', 'Na brodę... eee, Miedziobrodego! O czym ty mówisz?', 'Na brodę... eee, Miedziobrodego! O czym ty mówisz?', 0),
(11039, 'koKR', 'Jak mówiłem, trzymałem ten odłamek berła dobre pięćset lat i miałem z nim same kłopoty. Przyciągał najróżniejsze zainteresowanie – i to nie takie, jak trzeba. Chcę, żeby zostawiono mnie w spokoju z moimi badaniami, a nie niańczyć przepustkę do chwały jakiegoś niedoszłego bohatera. Więc... dałem go rybie.', '', 0),
(11040, 'koKR', 'Rybie? Dałeś rybie kawałek czegoś, co może być kluczem do ocalenia wszelkiego życia w Kalimdorze?', 'Rybie? Dałeś rybie kawałek czegoś, co może być kluczem do ocalenia wszelkiego życia w Kalimdorze?', 0),
(11041, 'koKR', 'Nie byle jakiej rybie, $gśmiertelniku:śmiertelniczko;. Tą rybą była płotka. Bardzo wyjątkowa płotka.', '', 0),
(11042, 'koKR', 'Płotka? Oceany są pełne płotek! Może ich tam być sto milionów!', 'Płotka? Oceany są pełne płotek! Może ich tam być sto milionów!', 0),
(11043, 'koKR', 'No właśnie!', '', 0),
(11045, 'koKR', 'Genialne, wiem... Nikt jej nigdy nie znajdzie; ale na wypadek, gdyby jednak ktoś ją znalazł, dałem płotce specjalne moce.', '', 0),
(11046, 'koKR', 'Umieściłeś ten kawałek w płotce, a płotkę wpuściłeś gdzieś do morza między tym miejscem a Wschodnimi Królestwami? I ta płotka ma specjalne moce?', 'Umieściłeś ten kawałek w płotce, a płotkę wpuściłeś gdzieś do morza między tym miejscem a Wschodnimi Królestwami? I ta płotka ma specjalne moce?', 0),
(11047, 'koKR', 'Zgadza się. $GSłuchałeś:Słuchałaś;! Ta płotka to naprawdę straszliwe stworzenie mojego własnego pomysłu. Gdy odpoczywam, lubię myśleć o pechowych rybakach, którzy na nią trafili i zostali połknięci w całości. Założę się, że byli nieźle zaskoczeni!$B$B<Azuregos się śmieje.>', '', 0),
(11048, 'koKR', 'Oszalałeś.', 'Oszalałeś.', 0),
(11049, 'koKR', 'Geniusz często bywa niezrozumiany. A teraz co do odłamka berła... Jeśli chcesz go zdobyć i nie zamierzasz spędzić kolejnych dziesięciu tysięcy lat na poszukiwaniach, musisz bardzo uważnie słuchać.', '', 0),
(11050, 'koKR', 'Zamieniam się w słuch.', 'Zamieniam się w słuch.', 0),
(11051, 'koKR', 'Dwa słowa: arkanitowa boja.', '', 0),
(11052, 'koKR', 'Słucham?', 'Słucham?', 0),
(11053, 'koKR', 'No dobrze... Musisz zbudować arkanitową boję i umieścić ją w oceanie. Moją płotkę przyciągnie magiczna emanacja. Gdy znajdzie się blisko boi – BUM! Boja wybuchnie wspaniałym impulsem tajemnej energii, który ujawni prawdziwą postać płotki. Możesz też ściągnąć na siebie gniew Neptulona, albo i nie. Powiedziałbym, że szanse są pół na pół.', '', 0),
(11054, 'koKR', 'Dobra, niech to sobie poukładam. Odłamek berła, który Anachronos powierzył twojemu Stadu, umieściłeś w płotce własnej roboty, a teraz oczekujesz, że zbuduję... arkanitową boję czy coś takiego... żeby zmusić twoją płotkę do wyjścia z kryjówki? I przy okazji być może ściągnę na siebie gniew Władcy Żywiołów? Coś $gpominąłem:pominęłam;? Może mam to zrobić bez ubrania, podczas zaćmienia słońca, w roku przestępnym?\n', 'Dobra, niech to sobie poukładam. Odłamek berła, który Anachronos powierzył twojemu Stadu, umieściłeś w płotce własnej roboty, a teraz oczekujesz, że zbuduję... arkanitową boję czy coś takiego... żeby zmusić twoją płotkę do wyjścia z kryjówki? I przy okazji być może ściągnę na siebie gniew Władcy Żywiołów? Coś $gpominąłem:pominęłam;? Może mam to zrobić bez ubrania, podczas zaćmienia słońca, w roku przestępnym?\n', 0),
(11056, 'koKR', 'Gdybym nie wiedział lepiej, pomyślałbym, że ze mnie drwisz, $gśmiertelniku:śmiertelniczko; – ale tak, w zasadzie wszystko się zgadza. Ubranie możesz zostawić na sobie.', '', 0),
(11057, 'koKR', 'DOBRA! A skąd, jeśli wolno spytać, mam wziąć arkanitową boję?', 'DOBRA! A skąd, jeśli wolno spytać, mam wziąć arkanitową boję?', 0),
(11058, 'koKR', 'Zanieś tę księgę rachunkową mojemu staremu znajomemu w Tanaris. Nazywa się Narain Wróżbiarz – okropny, okropny jasnowidz, ale niesamowity inżynier! On powinien się w tym wszystkim połapać.$B$BNie musisz dziękować, $N. To najmniej, co mogłem zrobić.$B$BMiłego dnia!', '', 0),
(11063, 'koKR', 'Nie $gpowinieneś:powinnaś; przypadkiem ratować świata?', '', 0),
(12363, 'koKR', 'Pragnę tej wiecznej kwintesencji, książę Hydraxisie.', 'Pragnę tej wiecznej kwintesencji, książę Hydraxisie.', 0),
(12364, 'koKR', '$GSłużyłeś:Służyłaś; naszej sprawie z wielką lojalnością, $N. Pozwól, że podaruję ci niewyczerpane źródło naszej żywiołowej kwintesencji.', '', 0),
(12365, 'koKR', 'Witaj z powrotem, $N. $GOkazałeś:Okazałaś; się $ggodnym sojusznikiem:godną sojuszniczką; w walce z Ragnarosem, a twoja obecność jest wśród nas zawsze mile widziana.', '', 0),
(36578, 'koKR', 'Pamiętam, jak z bratem biwakowaliśmy sami w dziczy Aszary. Spójrz na nią teraz.', '', 0),
(69357, 'koKR', '...', '', 0),
(77157, 'koKR', 'Ale...', 'Ale...', 0);
